head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > P > accessibility]<br/>MultiSelect 컴포넌트의 웹접근성 지원 기능을 일괄적으로 적용할지 설정합니다.",
    "validation" : [
        "true 설정 시 MultiSelect 컴포넌트에 웹접근성 지원 기능을 일괄적으로 적용합니다.",
        "true 설정 시 컴포넌트가 ul, li 태그로 렌더링되며 aria-activedescendant 등의 접근성 관련 HTML 속성이 추가됩니다.",
        "true 설정 시 위/아래 방향키로 아이템 간 포커스를 이동하고, Space 키로 선택/해제할 수 있습니다.",
        "true 설정 시 Ctrl 키 없이 클릭만으로 아이템을 토글 선택할 수 있습니다.",
        "false (default) 설정 시 웹접근성 지원 기능을 적용하지 않습니다.",
        "false 설정 시 컴포넌트가 table, tr 태그로 렌더링됩니다.",
        "false 설정 시 Ctrl+클릭으로 추가 선택, Shift+클릭으로 범위 선택을 할 수 있습니다.",
        "accessibility=true 이고 singleSelect=true 이면 Enter 키로도 아이템을 선택할 수 있습니다.",
        "accessibility=true 일때 nextTabID 속성을 설정하면 위/아래 방향키 대신 Tab, Shift+Tab 키로 아이템 간 포커스가 이동됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        accessibility : con_accessibility.getText(),
        singleSelect : con_singleSelect.getText(),
    }

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createLabel('label="* render 확인 : 페이지 로드 직후 클릭하여 태그/role 등 정적 접근성 속성 확인"', '', 'label1');
    $c.gcm.createLabel('label="* aria-activedescendant 확인 : ArrowDown 키 입력 후 클릭 (키 인터랙션 시점에 동적 추가됨, 로드 직후는 null)"', '', 'label2');
    $c.gcm.createLabel('label="* getValue 확인 : 아이템 클릭 또는 Space 키 입력 후 클릭하여 선택값/인덱스 확인"', '', 'label3');

    $c.gcm.createBasicMultiSelect(cList);
}



scwin.btn_getRender_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("render tagName : " + target1.render.tagName);

    let ulElem = document.querySelector("ul[id*='target1_ul']");
    let liElem = document.querySelector("li[id*='target1_li_item_0']");
    let tableElem = document.querySelector("table[id*='target1_table']");
    let trElem = document.querySelector("#" + target1.getID() + " tr");

    if (ulElem) {
        wf_body_bottom.getObj("scwin").setReturnValue("list tag : " + ulElem.tagName);
    }
    if (liElem) {
        wf_body_bottom.getObj("scwin").setReturnValue("item tag : " + liElem.tagName);
    }
    if (tableElem) {
        wf_body_bottom.getObj("scwin").setReturnValue("list tag : " + tableElem.tagName);
    }
    if (trElem) {
        wf_body_bottom.getObj("scwin").setReturnValue("item tag : " + trElem.tagName);
    }
};



scwin.btn_getAriaActivedescendant_onclick = function (e) {
    let ulElem = document.querySelector("ul[id*='target1_ul']");
    let activeId = ulElem ? ulElem.getAttribute('aria-activedescendant') : null;
    wf_body_bottom.getObj("scwin").setReturnValue("aria-activedescendant : " + activeId);
};



scwin.btn_getValue_onclick = function (e) {
    let value = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + value);
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex : " + target1.getSelectedIndex());
};
